// EN: Validate and prepare input data
// DE: Eingabedaten validieren und vorbereiten
const item = $input.item.json;

// Required fields check / Pflichtfelder prüfen
const requiredFields = ['eventTitle', 'eventDate', 'venue', 'city'];
const missingFields = requiredFields.filter(field => !item[field]);

if (missingFields.length > 0) {
  throw new Error(`Missing required fields: ${missingFields.join(', ')}`);
}

// Set defaults / Standardwerte setzen
const publishTo = item.publishTo || {
  twitter: true,
  instagram: true,
  facebook: true,
  linkedin: false,
  reddit: false,
  email: false
};

// Format date / Datum formatieren
let formattedDate = item.eventDate;
if (item.eventDate && item.eventTime) {
  const date = new Date(`${item.eventDate}T${item.eventTime}`);
  formattedDate = date.toLocaleDateString('de-DE', {
    weekday: 'long',
    year: 'numeric',
    month: 'long',
    day: 'numeric'
  });
}

// Prepare output / Ausgabe vorbereiten
return [{
  json: {
    eventTitle: item.eventTitle,
    eventDate: item.eventDate,
    eventTime: item.eventTime || '22:00',
    formattedDate: formattedDate,
    venue: item.venue,
    city: item.city,
    description: item.description || '',
    imageUrl: item.imageUrl || '',
    ticketUrl: item.ticketUrl || '',
    publishTo: publishTo,
    emailRecipients: item.emailRecipients || [],
    // Reddit-specific fields / Reddit-spezifische Felder
    redditSubreddit: item.redditSubreddit || '',
    redditFlair: item.redditFlair || '',
    redditNsfw: item.redditNsfw || false,
    redditSpoiler: item.redditSpoiler || false,
    redditPostType: item.redditPostType || 'text', // 'text' or 'link'
    timestamp: new Date().toISOString()
  }
}];

// EN: Validate platform credentials and requirements
// DE: Plattform-Credentials und Anforderungen validieren

const item = $input.item.json;

// Platform validation rules
const platformRules = {
  twitter: {
    required: ['eventTitle'],
    maxLength: 280,
    supports: ['text']
  },
  instagram: {
    required: ['eventTitle', 'imageUrl'],
    maxLength: 2200,
    supports: ['image', 'text']
  },
  facebook: {
    required: ['eventTitle'],
    maxLength: null, // No strict limit
    supports: ['text', 'image']
  },
  linkedin: {
    required: ['eventTitle'],
    maxLength: 3000,
    supports: ['text', 'image']
  },
  reddit: {
    required: ['eventTitle', 'redditSubreddit'],
    maxLength: null,
    supports: ['text', 'image']
  },
  email: {
    required: ['eventTitle', 'emailRecipients'],
    maxLength: null,
    supports: ['text', 'image', 'html']
  }
};

const validationResults = [];
let hasErrors = false;

// Check each enabled platform
for (const [platform, enabled] of Object.entries(item.publishTo || {})) {
  if (!enabled) continue;

  const rules = platformRules[platform];
  if (!rules) {
    validationResults.push({
      platform,
      valid: false,
      error: `Unknown platform: ${platform}`
    });
    hasErrors = true;
    continue;
  }

  // Check required fields
  const missingFields = rules.required.filter(field => !item[field]);
  if (missingFields.length > 0) {
    validationResults.push({
      platform,
      valid: false,
      error: `Missing required fields: ${missingFields.join(', ')}`
    });
    hasErrors = true;
    continue;
  }

  // Check content length if applicable
  if (rules.maxLength && item[`${platform}Text`] && item[`${platform}Text`].length > rules.maxLength) {
    validationResults.push({
      platform,
      valid: false,
      error: `Content too long: ${item[`${platform}Text`].length} > ${rules.maxLength} characters`
    });
    hasErrors = true;
    continue;
  }

  // Platform-specific validations
  if (platform === 'reddit' && !item.redditSubreddit) {
    validationResults.push({
      platform,
      valid: false,
      error: 'Reddit subreddit is required'
    });
    hasErrors = true;
    continue;
  }

  if (platform === 'email' && (!item.emailRecipients || item.emailRecipients.length === 0)) {
    validationResults.push({
      platform,
      valid: false,
      error: 'Email recipients are required'
    });
    hasErrors = true;
    continue;
  }

  validationResults.push({
    platform,
    valid: true,
    supports: rules.supports
  });
}

if (hasErrors) {
  throw new Error(`Platform validation failed:\n${validationResults
    .filter(r => !r.valid)
    .map(r => `${r.platform}: ${r.error}`)
    .join('\n')}`);
}

return [{
  json: {
    ...item,
    platformValidation: validationResults,
    validationPassed: true,
    validatedAt: new Date().toISOString()
  }
}];

// EN: Validate image and ticket URLs
// DE: Bild- und Ticket-URLs validieren

const item = $input.item.json;
const axios = require('axios');

async function validateUrl(url, timeout = 5000) {
  if (!url) return { valid: true, reachable: false }; // Optional URL

  try {
    // Basic URL format validation
    new URL(url);

    // Try to reach the URL (HEAD request for efficiency)
    const response = await axios.head(url, {
      timeout,
      headers: {
        'User-Agent': 'n8n-workflow/1.0 (URL Validation)'
      }
    });

    return {
      valid: true,
      reachable: response.status >= 200 && response.status < 400,
      statusCode: response.status,
      contentType: response.headers['content-type']
    };
  } catch (error) {
    return {
      valid: false,
      reachable: false,
      error: error.message,
      reason: error.code || 'Unknown error'
    };
  }
}

async function main() {
  const results = {};

  // Validate image URL
  if (item.imageUrl) {
    console.log(`🔍 Validating image URL: ${item.imageUrl}`);
    results.imageUrl = await validateUrl(item.imageUrl);

    if (results.imageUrl.valid && results.imageUrl.reachable) {
      // Check if it's actually an image
      const contentType = results.imageUrl.contentType;
      if (contentType && !contentType.startsWith('image/')) {
        results.imageUrl.warning = `URL does not point to an image (Content-Type: ${contentType})`;
      }
    }
  }

  // Validate ticket URL
  if (item.ticketUrl) {
    console.log(`🔍 Validating ticket URL: ${item.ticketUrl}`);
    results.ticketUrl = await validateUrl(item.ticketUrl);
  }

  // Check for validation errors
  const imageError = results.imageUrl && !results.imageUrl.valid;
  const ticketError = results.ticketUrl && !results.ticketUrl.valid;

  if (imageError || ticketError) {
    const errors = [];
    if (imageError) errors.push(`Image URL: ${results.imageUrl.error}`);
    if (ticketError) errors.push(`Ticket URL: ${results.ticketUrl.error}`);

    throw new Error(`URL validation failed:\n${errors.join('\n')}`);
  }

  // Log warnings
  if (results.imageUrl?.warning) {
    console.warn(`⚠️  ${results.imageUrl.warning}`);
  }

  return [{
    json: {
      ...item,
      urlValidation: results,
      urlsValidated: true,
      validatedAt: new Date().toISOString()
    }
  }];
}

return main();

