// EN: Generate relevant hashtags for different platforms
// DE: Relevante Hashtags für verschiedene Plattformen generieren

const item = $input.item.json;

// Base hashtags for different categories
const hashtagDatabase = {
  music: ['#Music', '#LiveMusic', '#Concert', '#DJ', '#Techno', '#House', '#Electronic'],
  location: (city) => [`#${city.replace(/\s+/g, '')}`, `#${city}Events`, `#${city}Nightlife`],
  event: ['#Event', '#Nightlife', '#Club', '#Party', '#Festival', '#LiveEvent'],
  platform: {
    instagram: ['#Instamusic', '#ClubLife', '#NightOut'],
    twitter: ['#NowPlaying', '#MusicEvent'],
    facebook: ['#LocalEvent', '#Community'],
    linkedin: ['#Networking', '#ProfessionalEvent'],
    reddit: ['#MusicCommunity', '#EventShare']
  }
};

function generateHashtags() {
  const hashtags = new Set();

  // Add music-related hashtags
  hashtagDatabase.music.forEach(tag => hashtags.add(tag));

  // Add location-based hashtags
  if (item.city) {
    const locationTags = hashtagDatabase.location(item.city);
    locationTags.forEach(tag => hashtags.add(tag));
  }

  // Add event-related hashtags
  hashtagDatabase.event.forEach(tag => hashtags.add(tag));

  // Add platform-specific hashtags
  for (const [platform, enabled] of Object.entries(item.publishTo || {})) {
    if (enabled && hashtagDatabase.platform[platform]) {
      hashtagDatabase.platform[platform].forEach(tag => hashtags.add(tag));
    }
  }

  // Extract hashtags from description
  if (item.description) {
    const descriptionHashtags = item.description.match(/#\w+/g);
    if (descriptionHashtags) {
      descriptionHashtags.forEach(tag => hashtags.add(tag));
    }
  }

  // Convert to array and sort
  const result = Array.from(hashtags).sort();

  // Limit to reasonable amount per platform
  const limits = {
    twitter: 5,      // Twitter prefers fewer hashtags
    instagram: 10,   // Instagram can handle more
    facebook: 8,
    linkedin: 3,     // LinkedIn prefers professional look
    reddit: 5,
    email: 0         // Email usually doesn't need hashtags
  };

  return result.slice(0, limits[item.currentPlatform] || 5);
}

// Generate hashtags for each platform
const enhancedItem = { ...item };

for (const [platform, enabled] of Object.entries(item.publishTo || {})) {
  if (enabled) {
    // Temporarily set current platform for hashtag generation
    enhancedItem.currentPlatform = platform;
    const platformHashtags = generateHashtags();

    // Add hashtags to platform-specific text
    const textKey = `${platform}Text`;
    if (enhancedItem[textKey]) {
      // Only add hashtags if not already present
      const existingHashtags = enhancedItem[textKey].match(/#\w+/g) || [];
      const newHashtags = platformHashtags.filter(tag => !existingHashtags.includes(tag));

      if (newHashtags.length > 0) {
        enhancedItem[textKey] += '\n\n' + newHashtags.join(' ');
      }
    }

    enhancedItem[`${platform}Hashtags`] = platformHashtags;
  }
}

return [{
  json: {
    ...enhancedItem,
    hashtagsGenerated: true,
    generatedAt: new Date().toISOString()
  }
}];

// EN: Collect results from all posting operations
// DE: Sammelt Ergebnisse aller Posting-Operationen
const results = [];
const allItems = $input.all();

// Get original event data from first item / Hole ursprüngliche Event-Daten vom ersten Item
const inputData = allItems[0]?.json || {};

// Platform detection from data / Plattform-Erkennung aus Daten
const detectPlatform = (item) => {
  // Check for platform-specific fields / Prüfe plattform-spezifische Felder
  if (item.id_str || item.id) return 'Twitter/X';
  if (item.instagram_id || item.media_id) return 'Instagram';
  if (item.post_id || item.facebook_id) return 'Facebook';
  if (item.linkedin_id || item.urn) return 'LinkedIn';
  if (item.messageId || item.emailId) return 'Email';
  if (item.name && item.name.startsWith('t3_')) return 'Reddit';
  // Fallback: check for error or success indicators / Fallback: Prüfe Fehler- oder Erfolgs-Indikatoren
  if (item.error) return 'Unknown Platform';
  return 'Unknown Platform';
};

// Collect all outputs / Alle Ausgaben sammeln
allItems.forEach((item) => {
  const platform = detectPlatform(item.json);
  const hasError = item.json.error || item.json.errorMessage || false;

  results.push({
    platform: platform,
    success: !hasError,
    data: item.json,
    timestamp: new Date().toISOString()
  });
});

// If no results collected, create summary from input / Falls keine Ergebnisse gesammelt, erstelle Zusammenfassung aus Eingabe
if (results.length === 0 && inputData.eventTitle) {
  results.push({
    platform: 'No platforms enabled',
    success: true,
    data: { message: 'No platforms were enabled for posting' },
    timestamp: new Date().toISOString()
  });
}

return [{
  json: {
    eventTitle: inputData.eventTitle || 'Unknown Event',
    eventDate: inputData.eventDate || '',
    timestamp: new Date().toISOString(),
    results: results,
    summary: {
      total: results.length,
      successful: results.filter(r => r.success).length,
      failed: results.filter(r => !r.success).length
    }
  }
}];

// EN: Enhanced logging and monitoring for all posting operations
// DE: Erweiterte Protokollierung und Überwachung aller Posting-Operationen

const item = $input.item.json;

// Create detailed execution log
const executionLog = {
  eventId: `${item.eventTitle}-${Date.now()}`,
  timestamp: new Date().toISOString(),
  event: {
    title: item.eventTitle,
    date: item.eventDate,
    venue: item.venue,
    city: item.city
  },
  platforms: {},
  summary: {
    totalPlatforms: 0,
    successful: 0,
    failed: 0,
    skipped: 0
  }
};

// Analyze platform results
if (item.results && Array.isArray(item.results)) {
  item.results.forEach(result => {
    executionLog.summary.totalPlatforms++;

    executionLog.platforms[result.platform] = {
      success: result.success,
      timestamp: result.timestamp,
      data: result.data
    };

    if (result.success) {
      executionLog.summary.successful++;
    } else {
      executionLog.summary.failed++;
    }
  });
}

// Calculate skipped platforms
const enabledPlatforms = Object.keys(item.publishTo || {}).filter(p => item.publishTo[p]);
executionLog.summary.skipped = enabledPlatforms.length - executionLog.summary.totalPlatforms;

// Performance metrics
executionLog.performance = {
  totalDuration: Date.now() - new Date(item.timestamp).getTime(),
  platformsPerSecond: executionLog.summary.totalPlatforms / ((Date.now() - new Date(item.timestamp).getTime()) / 1000)
};

// Generate human-readable summary
let summaryText = `🎫 Event: ${item.eventTitle}\n`;
summaryText += `📅 Date: ${item.formattedDate}\n`;
summaryText += `📍 Location: ${item.venue}, ${item.city}\n\n`;

summaryText += `📊 Posting Results:\n`;
summaryText += `✅ Successful: ${executionLog.summary.successful}\n`;
summaryText += `❌ Failed: ${executionLog.summary.failed}\n`;
summaryText += `⏭️  Skipped: ${executionLog.summary.skipped}\n\n`;

if (executionLog.summary.failed > 0) {
  summaryText += `⚠️  Failed Platforms:\n`;
  Object.entries(executionLog.platforms).forEach(([platform, data]) => {
    if (!data.success) {
      summaryText += `• ${platform}: ${data.data?.error || 'Unknown error'}\n`;
    }
  });
}

// Log to console for n8n logs
console.log('='.repeat(50));
console.log('🎫 MULTI-PLATFORM POSTING LOG');
console.log('='.repeat(50));
console.log(summaryText);
console.log(`⏱️  Total Duration: ${executionLog.performance.totalDuration}ms`);
console.log('='.repeat(50));

// Return enhanced data
return [{
  json: {
    ...item,
    executionLog: executionLog,
    summaryText: summaryText,
    logGenerated: true
  }
}];

// EN: Send notifications to Discord/Telegram about posting results
// DE: Sende Benachrichtigungen an Discord/Telegram über Posting-Ergebnisse

const item = $input.item.json;
const axios = require('axios');

async function sendDiscordNotification(webhookUrl, message) {
  try {
    await axios.post(webhookUrl, {
      content: message,
      embeds: [{
        title: "🎫 Multi-Platform Event Posting",
        description: item.summaryText,
        color: item.executionLog?.summary?.failed > 0 ? 0xff0000 : 0x00ff00,
        fields: [
          {
            name: "📊 Results",
            value: `✅ ${item.executionLog?.summary?.successful || 0} | ❌ ${item.executionLog?.summary?.failed || 0} | ⏭️ ${item.executionLog?.summary?.skipped || 0}`,
            inline: true
          },
          {
            name: "⏱️ Duration",
            value: `${item.executionLog?.performance?.totalDuration || 0}ms`,
            inline: true
          },
          {
            name: "📅 Event",
            value: `${item.eventTitle} - ${item.formattedDate}`,
            inline: false
          }
        ],
        timestamp: new Date().toISOString()
      }]
    });
    return { platform: 'discord', success: true };
  } catch (error) {
    return { platform: 'discord', success: false, error: error.message };
  }
}

async function sendTelegramNotification(botToken, chatId, message) {
  try {
    const url = `https://api.telegram.org/bot${botToken}/sendMessage`;
    await axios.post(url, {
      chat_id: chatId,
      text: message,
      parse_mode: 'HTML',
      disable_web_page_preview: true
    });
    return { platform: 'telegram', success: true };
  } catch (error) {
    return { platform: 'telegram', success: false, error: error.message };
  }
}

async function main() {
  const notifications = [];

  // Discord Notification
  const discordWebhook = $env.DISCORD_WEBHOOK_URL;
  if (discordWebhook) {
    console.log('📢 Sending Discord notification...');
    const discordResult = await sendDiscordNotification(discordWebhook, item.summaryText);
    notifications.push(discordResult);

    if (discordResult.success) {
      console.log('✅ Discord notification sent');
    } else {
      console.error('❌ Discord notification failed:', discordResult.error);
    }
  }

  // Telegram Notification
  const telegramBotToken = $env.TELEGRAM_BOT_TOKEN;
  const telegramChatId = $env.TELEGRAM_CHAT_ID;

  if (telegramBotToken && telegramChatId) {
    console.log('📢 Sending Telegram notification...');

    // Format message for Telegram (HTML)
    const telegramMessage = `
🎫 <b>Multi-Platform Event Posting</b>

📅 <b>${item.eventTitle}</b>
📍 ${item.venue}, ${item.city}
🕐 ${item.formattedDate}

📊 <b>Results:</b>
✅ Successful: ${item.executionLog?.summary?.successful || 0}
❌ Failed: ${item.executionLog?.summary?.failed || 0}
⏭️ Skipped: ${item.executionLog?.summary?.skipped || 0}

⏱️ Duration: ${item.executionLog?.performance?.totalDuration || 0}ms
    `.trim();

    const telegramResult = await sendTelegramNotification(telegramBotToken, telegramChatId, telegramMessage);
    notifications.push(telegramResult);

    if (telegramResult.success) {
      console.log('✅ Telegram notification sent');
    } else {
      console.error('❌ Telegram notification failed:', telegramResult.error);
    }
  }

  // If no notification methods configured, log to console
  if (notifications.length === 0) {
    console.log('ℹ️  No notification methods configured');
    console.log('📊 Posting Summary:');
    console.log(item.summaryText);
  }

  return [{
    json: {
      ...item,
      notifications: notifications,
      notificationsSent: notifications.length > 0,
      notificationTimestamp: new Date().toISOString()
    }
  }];
}

return main();
